  if(mode==='strong')return students.filter(s=>(s.verifiedEvidence>0&&s.avgScore!=null&&s.avgScore>=8)||(s.verifiedEvidence===0&&s.practiceAccuracy!=null&&s.practiceAccuracy>=.8));
  if(mode==='new')return students.filter(s=>s.submitted===0&&s.avgScore==null&&s.practiceAccuracy==null);
  if(mode==='developing'){const support=new Set(firebaseSmartTargetStudents(c,'support').map(x=>x.uid)),strong=new Set(firebaseSmartTargetStudents(c,'strong').map(x=>x.uid));return students.filter(s=>(s.avgScore!=null||s.practiceAccuracy!=null)&&!support.has(s.uid)&&!strong.has(s.uid))}
