    if(a?.submission)return alert('Em đã nộp bài này. Giáo viên có thể cho làm lại nếu cần.');
    if(!a){let [snap,idx]=await Promise.all([firebaseAssignmentsRef(classId).doc(assignmentId).get(),firebaseSubmissionIndexRef(classId).doc(firebaseSubmissionIndexId(assignmentId,firebaseUser.uid)).get()]);if(!snap.exists)return alert('Bài giao không còn tồn tại.');if(idx.exists)return alert('Em đã nộp bài này. Giáo viên có thể cho làm lại nếu cần.');a={id:assignmentId,classId,...snap.data()}}
